// The seven module groups (folder ownership) and the PRD's thirteen Book VI modules plus the Book VII
// supplemental entries [DOC:pp.244-282] (asserted). A group is a folder under src/modules/; a PRD
// module is a sidebar section. Foundation-owned: module agents do not edit this file.

export type ModuleGroup =
  | "sales"
  | "materials"
  | "engineering"
  | "planning-production"
  | "quality-trace"
  | "purchasing-finance"
  | "admin"
  | "shell"
  | "inventory-ops"
  | "target-state"

export type PrdModule =
  | "Materials"
  | "Sales"
  | "Returns"
  | "Engineering"
  | "CAD and Documents"
  | "Planning"
  | "Production"
  | "Quality"
  | "Purchasing"
  | "Costing and Pricing"
  | "Controlling"
  | "Traceability and Barcode"
  | "Workflow and Administration"
  | "Inventory (Book VII)"
  // Feature-list modules (user feature list, Oct 2026): shell, dashboards, print, inventory operations
  | "Global Shell and System States"
  | "Home and Dashboards"
  | "Component Library"
  | "Print Outputs"
  | "Flow Prototypes and Handoff"
  | "Inventory Operations"
  // Book IX target-state modules (later phase, activation per the decision register)
  | "Full EDI"
  | "Periodic Actual Costing and Material Ledger"
  | "Advanced Scheduling Optimizer"
  | "Global Multi-Plant ATP and CTP"
  | "Supplier and Customer Portals"
  | "Machine Integration, OEE and Downtime"
  | "Field Service Management"
  | "Plant Maintenance and EAM"
  | "International Localization"
  | "Carrier Integration"

export const GROUPS: { id: ModuleGroup; label: string; modules: PrdModule[] }[] = [
  { id: "sales", label: "Sales and service", modules: ["Sales", "Returns"] },
  { id: "materials", label: "Materials and inventory", modules: ["Materials", "Inventory (Book VII)"] },
  { id: "engineering", label: "Engineering", modules: ["Engineering", "CAD and Documents"] },
  { id: "planning-production", label: "Planning and production", modules: ["Planning", "Production"] },
  { id: "quality-trace", label: "Quality and traceability", modules: ["Quality", "Traceability and Barcode"] },
  { id: "purchasing-finance", label: "Purchasing and finance", modules: ["Purchasing", "Costing and Pricing", "Controlling"] },
  { id: "admin", label: "Workflow and administration", modules: ["Workflow and Administration"] },
  {
    id: "shell",
    label: "Shell, dashboards, components and print",
    modules: ["Global Shell and System States", "Home and Dashboards", "Component Library", "Print Outputs", "Flow Prototypes and Handoff"],
  },
  { id: "inventory-ops", label: "Inventory operations", modules: ["Inventory Operations"] },
  {
    id: "target-state",
    label: "Target state (phased, Book IX)",
    modules: [
      "Full EDI",
      "Periodic Actual Costing and Material Ledger",
      "Advanced Scheduling Optimizer",
      "Global Multi-Plant ATP and CTP",
      "Supplier and Customer Portals",
      "Machine Integration, OEE and Downtime",
      "Field Service Management",
      "Plant Maintenance and EAM",
      "International Localization",
      "Carrier Integration",
    ],
  },
]

/** Sidebar sections. A section is a list of PRD modules; it is not the same as a folder group (the
 *  shell group feeds three sections, so "Home and dashboards", "Print outputs" and the shell/components
 *  section each show on their own). Foundation-owned. */
export const SECTIONS: { id: string; label: string; modules: PrdModule[] }[] = [
  { id: "home", label: "Home and dashboards", modules: ["Home and Dashboards"] },
  ...GROUPS.filter((g) => !["shell", "inventory-ops", "target-state"].includes(g.id)).map((g) => ({ id: g.id, label: g.label, modules: g.modules })),
  { id: "inventory-ops", label: "Inventory operations", modules: ["Inventory Operations"] },
  { id: "print", label: "Print outputs", modules: ["Print Outputs"] },
  { id: "shell", label: "Global shell, components and handoff", modules: ["Global Shell and System States", "Component Library", "Flow Prototypes and Handoff"] },
  { id: "target-state", label: "Target state (phased)", modules: GROUPS.find((g) => g.id === "target-state")!.modules },
]

export const groupOfModule = (m: PrdModule): ModuleGroup => GROUPS.find((g) => g.modules.includes(m))!.id
